//go:build duckdb_arrow

package duckplane

// TestParquetTypesMatchGolden drives every golden input type through the
// DuckDB writer and compares the Parquet it writes with what today's Go writer
// wrote (testdata/parquet-types.golden.json, generated by
// pkg/datagateway/buffer TestGoldenParquetTypes). The inputs below are a copy
// of that generator's goldenInputs; the file is read with the same arrow-go
// Parquet reader the generator used, so physical/logical/converted types,
// field ids, the Arrow read type and the values compare as the same strings.

import (
	"context"
	"encoding/json"
	"os"
	"strings"
	"testing"

	"github.com/apache/arrow-go/v18/arrow"
	"github.com/apache/arrow-go/v18/arrow/array"
	"github.com/apache/arrow-go/v18/arrow/memory"
	"github.com/apache/arrow-go/v18/parquet/file"
	"github.com/apache/arrow-go/v18/parquet/pqarrow"

	"github.com/datuplet/datuplet/pkg/datagateway"
)

type goldenInput struct {
	name           string
	dt             arrow.DataType
	chunk1, chunk2 string
}

// goldenInputs mirrors pkg/datagateway/buffer/golden_types_test.go.
func goldenInputs() []goldenInput {
	ts := func(unit arrow.TimeUnit, tz string) arrow.DataType {
		return &arrow.TimestampType{Unit: unit, TimeZone: tz}
	}
	tsCases := func(name string, unit arrow.TimeUnit, tz string, c1, c2 string) goldenInput {
		return goldenInput{name: name, dt: ts(unit, tz), chunk1: c1, chunk2: c2}
	}
	var in []goldenInput
	in = append(in,
		goldenInput{"int8", arrow.PrimitiveTypes.Int8, `[-128, null, 127]`, `[0, 1, null]`},
		goldenInput{"int16", arrow.PrimitiveTypes.Int16, `[-32768, null, 32767]`, `[0, 1, null]`},
		goldenInput{"int32", arrow.PrimitiveTypes.Int32, `[-2147483648, null, 2147483647]`, `[0, 1, null]`},
		goldenInput{"int64", arrow.PrimitiveTypes.Int64, `[-9223372036854775808, null, 9223372036854775807]`, `[0, 1, null]`},
		goldenInput{"uint8", arrow.PrimitiveTypes.Uint8, `[0, null, 255]`, `[1, 128, null]`},
		goldenInput{"uint16", arrow.PrimitiveTypes.Uint16, `[0, null, 65535]`, `[1, 32768, null]`},
		goldenInput{"uint32", arrow.PrimitiveTypes.Uint32, `[0, null, 4294967295]`, `[1, 2147483648, null]`},
		goldenInput{"uint64", arrow.PrimitiveTypes.Uint64, `[0, null, 18446744073709551615]`, `[1, 9223372036854775808, null]`},
		goldenInput{"float32", arrow.PrimitiveTypes.Float32, `[-3.4028235e38, null, 3.4028235e38]`, `[0.5, -0.25, null]`},
		goldenInput{"float64", arrow.PrimitiveTypes.Float64, `[-1.7976931348623157e308, null, 1.7976931348623157e308]`, `[0.5, -0.25, null]`},
		goldenInput{"string", arrow.BinaryTypes.String, `["héllo", null, ""]`, `["a", "", null]`},
		goldenInput{"large_string", arrow.BinaryTypes.LargeString, `["héllo", null, ""]`, `["a", "", null]`},
		goldenInput{"bool", arrow.FixedWidthTypes.Boolean, `[true, null, false]`, `[false, true, null]`},
	)
	for _, tz := range []string{"", "UTC"} {
		suffix := ""
		if tz != "" {
			suffix = "_tz_utc"
		}
		in = append(in,
			tsCases("timestamp_s"+suffix, arrow.Second, tz,
				`["1900-01-01T00:00:00Z", null, "2100-01-01T00:00:00Z"]`,
				`["1970-01-01T00:00:00Z", "1969-12-31T23:59:59Z", null]`),
			tsCases("timestamp_ms"+suffix, arrow.Millisecond, tz,
				`["1900-01-01T00:00:00Z", null, "2100-01-01T00:00:00.123Z"]`,
				`["1970-01-01T00:00:00Z", "1969-12-31T23:59:59.999Z", null]`),
			tsCases("timestamp_us"+suffix, arrow.Microsecond, tz,
				`["1900-01-01T00:00:00Z", null, "2100-01-01T00:00:00.123456Z"]`,
				`["1970-01-01T00:00:00Z", "1969-12-31T23:59:59.999999Z", null]`),
			tsCases("timestamp_ns"+suffix, arrow.Nanosecond, tz,
				`["1900-01-01T00:00:00Z", null, "2100-01-01T00:00:00.123456789Z"]`,
				`["1970-01-01T00:00:00Z", "1969-12-31T23:59:59.999999999Z", null]`),
		)
	}
	in = append(in,
		goldenInput{"date32", arrow.FixedWidthTypes.Date32, `[-1, null, 19000]`, `[0, 1, null]`},
		goldenInput{"date64", arrow.FixedWidthTypes.Date64, `[-86400000, null, 1641600000000]`, `[0, 86400000, null]`},
		goldenInput{"binary", arrow.BinaryTypes.Binary, `["AP8=", null, ""]`, `["YQ==", "", null]`},
		goldenInput{"large_binary", arrow.BinaryTypes.LargeBinary, `["AP8=", null, ""]`, `["YQ==", "", null]`},
	)
	return in
}

type goldenColumn struct {
	Name          string `json:"name"`
	PhysicalType  string `json:"physical_type"`
	LogicalType   string `json:"logical_type"`
	ConvertedType string `json:"converted_type"`
	Repetition    string `json:"repetition"`
	HasFieldID    bool   `json:"field_id_present"`
	ArrowReadType string `json:"arrow_read_type"`
}

type goldenEntry struct {
	InputType string         `json:"input_type"`
	Accepted  bool           `json:"accepted"`
	Error     string         `json:"error,omitempty"`
	Files     int            `json:"parquet_files,omitempty"`
	Rows      int64          `json:"rows,omitempty"`
	Columns   []goldenColumn `json:"columns,omitempty"`
	Values    []string       `json:"values,omitempty"`
}

// knownDeviations are golden columns DuckDB cannot reproduce, accepted by
// maintainer ruling 2026-11-01 (spec docs/superpowers/specs/
// 2026-10-31-duckdb-gateway-design.md, Write path item 6). DuckDB has no
// millisecond (or second) UTC-adjusted timestamp type: TIMESTAMPTZ is
// microseconds, so a UTC timestamp in s/ms is written as UTC microseconds
// (same instants, finer unit; Iceberg's timestamptz is microseconds anyway).
// The values still round-trip exactly; only the unit-derived fields differ.
var knownDeviations = map[string]goldenColumn{
	"timestamp_s_tz_utc":  utcMicros,
	"timestamp_ms_tz_utc": utcMicros,
}

var utcMicros = goldenColumn{
	Name:          "v",
	PhysicalType:  "INT64",
	LogicalType:   "Timestamp(isAdjustedToUTC=true, timeUnit=microseconds, is_from_converted_type=false, force_set_converted_type=false)",
	ConvertedType: "TIMESTAMP_MICROS",
	Repetition:    "optional",
	ArrowReadType: "timestamp[us, tz=UTC]",
}

func loadGolden(t *testing.T) map[string]goldenEntry {
	t.Helper()
	raw, err := os.ReadFile("testdata/parquet-types.golden.json")
	if err != nil {
		t.Fatalf("golden: %v", err)
	}
	var g struct {
		Entries []goldenEntry `json:"entries"`
	}
	if err := json.Unmarshal(raw, &g); err != nil {
		t.Fatalf("golden: %v", err)
	}
	out := map[string]goldenEntry{}
	for _, e := range g.Entries {
		out[e.InputType] = e
	}
	return out
}

func TestParquetTypesMatchGolden(t *testing.T) {
	golden := loadGolden(t)
	inputs := goldenInputs()
	if len(inputs) != len(golden) {
		t.Fatalf("%d inputs, %d golden entries", len(inputs), len(golden))
	}
	p := testPlane(t)
	mem := memory.NewGoAllocator()
	for _, in := range inputs {
		t.Run(in.name, func(t *testing.T) {
			want, ok := golden[in.name]
			if !ok {
				t.Fatalf("no golden entry")
			}
			sch := arrow.NewSchema([]arrow.Field{{Name: "v", Type: in.dt, Nullable: true}}, nil)
			dir := t.TempDir() + "/"
			w, err := p.OpenTableWriter(context.Background(), datagateway.WriterSpec{
				DataPrefix: dir, FilePrefix: "part-golden-w", Schema: sch,
			})
			if !want.Accepted {
				if err == nil || !strings.Contains(err.Error(), "unsupported Arrow type") {
					if w != nil {
						w.Abort()
					}
					t.Fatalf("rejected type opened: %v (golden error: %s)", err, want.Error)
				}
				return
			}
			if err != nil {
				t.Fatalf("OpenTableWriter: %v", err)
			}
			for _, js := range []string{in.chunk1, in.chunk2} {
				arr, _, err := array.FromJSON(mem, in.dt, strings.NewReader(js))
				if err != nil {
					t.Fatal(err)
				}
				rec := array.NewRecordBatch(sch, []arrow.Array{arr}, int64(arr.Len()))
				arr.Release()
				err = w.Write(context.Background(), rec)
				rec.Release()
				if err != nil {
					t.Fatalf("Write: %v", err)
				}
			}
			files, err := w.Close(context.Background())
			if err != nil {
				t.Fatalf("Close: %v", err)
			}
			if len(files) != want.Files {
				t.Fatalf("files = %d, golden %d", len(files), want.Files)
			}
			var rows int64
			var values []string
			for fi, f := range files {
				cols, vals, n := readParquet(t, f.Path)
				if n != f.Rows {
					t.Fatalf("stats rows %d, file rows %d", f.Rows, n)
				}
				rows += n
				values = append(values, vals...)
				if fi > 0 {
					continue
				}
				wantCols := want.Columns
				if dev, ok := knownDeviations[in.name]; ok {
					wantCols = []goldenColumn{dev}
				}
				if len(cols) != len(wantCols) {
					t.Fatalf("columns %+v, golden %+v", cols, wantCols)
				}
				for i := range cols {
					// Every column is OPTIONAL by design (spec, Write path 3).
					if cols[i].Repetition != "optional" {
						t.Errorf("column %d repetition %q, want optional", i, cols[i].Repetition)
					}
					cols[i].Repetition = wantCols[i].Repetition
					if cols[i] != wantCols[i] {
						t.Errorf("column %d:\n got    %+v\n golden %+v", i, cols[i], wantCols[i])
					}
				}
			}
			if rows != want.Rows {
				t.Errorf("rows = %d, golden %d", rows, want.Rows)
			}
			if strings.Join(values, "\x00") != strings.Join(want.Values, "\x00") {
				t.Errorf("values = %q, golden %q", values, want.Values)
			}
		})
	}
}

// readParquet reads a file the way the golden generator does.
func readParquet(t *testing.T, path string) ([]goldenColumn, []string, int64) {
	t.Helper()
	rdr, err := file.OpenParquetFile(path, false)
	if err != nil {
		t.Fatalf("open parquet: %v", err)
	}
	defer rdr.Close()
	fr, err := pqarrow.NewFileReader(rdr, pqarrow.ArrowReadProperties{}, memory.NewGoAllocator())
	if err != nil {
		t.Fatalf("pqarrow: %v", err)
	}
	as, err := fr.Schema()
	if err != nil {
		t.Fatalf("arrow schema: %v", err)
	}
	pq := rdr.MetaData().Schema
	var cols []goldenColumn
	for c := 0; c < pq.NumColumns(); c++ {
		col := pq.Column(c)
		node := col.SchemaNode()
		gc := goldenColumn{
			Name:          col.Name(),
			PhysicalType:  col.PhysicalType().String(),
			LogicalType:   col.LogicalType().String(),
			ConvertedType: col.ConvertedType().String(),
			Repetition:    node.RepetitionType().String(),
			HasFieldID:    node.FieldID() >= 0,
		}
		if c < as.NumFields() {
			gc.ArrowReadType = as.Field(c).Type.String()
		}
		cols = append(cols, gc)
	}
	tbl, err := fr.ReadTable(context.Background())
	if err != nil {
		t.Fatalf("read table: %v", err)
	}
	defer tbl.Release()
	var vals []string
	for _, ch := range tbl.Column(0).Data().Chunks() {
		for r := 0; r < ch.Len(); r++ {
			vals = append(vals, ch.ValueStr(r))
		}
	}
	return cols, vals, tbl.NumRows()
}

// TestTimestampZonesMatchToday: timestamps in a zone other than UTC were
// accepted by today's writer and written exactly like UTC ones (probe of
// pkg/datagateway/buffer at main ecff5c5; see task-3-report.md, fix round 2).
// Each unit × zone must produce the Parquet column of the UTC golden entry for
// that unit (including the accepted s/ms micros deviation) and read back the
// same instants. Only the Arrow read type's zone name differs: today's file
// embedded the Arrow schema (zone name kept), DuckDB's reads back as UTC.
func TestTimestampZonesMatchToday(t *testing.T) {
	golden := loadGolden(t)
	p := testPlane(t)
	mem := memory.NewGoAllocator()
	for _, in := range goldenInputs() {
		ts, ok := in.dt.(*arrow.TimestampType)
		if !ok || ts.TimeZone != "UTC" {
			continue
		}
		utc := golden[in.name]
		wantCol := utc.Columns[0]
		if dev, ok := knownDeviations[in.name]; ok {
			wantCol = dev
		}
		for _, zone := range []string{"Europe/Prague", "+01:00", "America/New_York"} {
			t.Run(in.name+"/"+zone, func(t *testing.T) {
				dt := &arrow.TimestampType{Unit: ts.Unit, TimeZone: zone}
				sch := arrow.NewSchema([]arrow.Field{{Name: "v", Type: dt, Nullable: true}}, nil)
				w, err := p.OpenTableWriter(context.Background(), datagateway.WriterSpec{
					DataPrefix: t.TempDir() + "/", FilePrefix: "part-zone-w", Schema: sch,
				})
				if err != nil {
					t.Fatalf("OpenTableWriter: %v", err)
				}
				for _, js := range []string{in.chunk1, in.chunk2} {
					arr, _, err := array.FromJSON(mem, dt, strings.NewReader(js))
					if err != nil {
						t.Fatal(err)
					}
					rec := array.NewRecordBatch(sch, []arrow.Array{arr}, int64(arr.Len()))
					arr.Release()
					err = w.Write(context.Background(), rec)
					rec.Release()
					if err != nil {
						t.Fatalf("Write: %v", err)
					}
				}
				files, err := w.Close(context.Background())
				if err != nil || len(files) != 1 {
					t.Fatalf("Close = %+v, %v", files, err)
				}
				cols, vals, n := readParquet(t, files[0].Path)
				if len(cols) != 1 || cols[0] != wantCol {
					t.Errorf("column:\n got  %+v\n want %+v", cols, wantCol)
				}
				// Values render in UTC, so equal strings mean equal instants.
				if n != utc.Rows || strings.Join(vals, "\x00") != strings.Join(utc.Values, "\x00") {
					t.Errorf("values = %q (%d rows), want instants %q", vals, n, utc.Values)
				}
			})
		}
	}
}
